 public class HeadingSize:System.Windows.Data.IValueConverter {
  public object Convert(object value,Type type,object parameter,System.Globalization.CultureInfo culture){return (double)value*(System.Convert.ToInt32(parameter)==1?1.5:System.Convert.ToInt32(parameter)==2?1.18:1);}
  public object ConvertBack(object value,Type type,object parameter,System.Globalization.CultureInfo culture){throw new NotSupportedException();}
 }
 public class Paragraph { public string Text {get;set;} public int Kind {get;set;} public int Index {get;set;} public bool Markdown {get;set;} public List<ReadingImage> BeforeImages=new List<ReadingImage>();public List<ReadingImage> AfterImages=new List<ReadingImage>(); public string Display {get {return String.IsNullOrEmpty(Text)?"图片":Text.Length>65?Text.Substring(0,65)+"…":Text;}} }
 public class Book {
  public string Path {get;set;} public string Id {get;set;} public string SourcePath {get;set;} public string Title {get;set;} public string Author {get;set;} public string Format {get;set;} public string LastChapter {get;set;} public string LastReadUtc {get;set;} public string Encoding="自动";
  public int VisualPart=-1; public int PageCharacter; public double Progress=-1; public int Position {get;set;} public int TotalBlocks {get;set;} public double ParagraphOffset {get;set;} public List<int> Marks = new List<int>();
  [XmlIgnore] public string Name {get{return String.IsNullOrWhiteSpace(Title)?System.IO.Path.GetFileNameWithoutExtension(SourcePath??Path):Title;}}
  [XmlIgnore] public string Detail {get{return (Format??System.IO.Path.GetExtension(Path).TrimStart('.').ToUpperInvariant())+"  ·  "+(TotalBlocks>0?String.Format("{0:0.0}%",Progress>=0?Progress*100:100.0*Position/Math.Max(1,TotalBlocks-1)):"尚未阅读")+(String.IsNullOrEmpty(Author)?"":"  ·  "+Author);}}
  [XmlIgnore] public string ResumeLabel {get{return String.IsNullOrEmpty(LastChapter)?(Position>0?"继续阅读 · 第 "+(Position+1).ToString("N0")+" 段":"开始阅读"):"继续阅读 · "+LastChapter;}}
  public override string ToString(){return Name;}
 }
