 public partial class Document {
  public List<Paragraph> Blocks=new List<Paragraph>(); public List<Paragraph> Chapters=new List<Paragraph>(); public long Characters; public string EncodingName; public string Title; public string Author;
  public static Document Read(string path,string forced) {
   string extension=System.IO.Path.GetExtension(path).ToLowerInvariant();if(extension!=".txt"&&extension!=".md"&&extension!=".markdown")return Formats.Read(path);
   var info=new FileInfo(path); if(info.Length>250L*1024*1024) throw new Exception("文件超过 250 MB，请先拆分后阅读。");
   byte[] bytes=File.ReadAllBytes(path); Encoding enc;
   if(forced=="GB18030") enc=Encoding.GetEncoding("GB18030");
   else if(forced=="UTF-8") enc=new UTF8Encoding(false,true);
   else if(bytes.Length>=2 && bytes[0]==255 && bytes[1]==254) enc=Encoding.Unicode;
   else if(bytes.Length>=2 && bytes[0]==254 && bytes[1]==255) enc=Encoding.BigEndianUnicode;
   else {enc=new UTF8Encoding(false,true); try{enc.GetCharCount(bytes);}catch(DecoderFallbackException){enc=Encoding.GetEncoding("GB18030");}}
   string body=enc.GetString(bytes).TrimStart('\uFEFF'); var doc=new Document{Characters=body.Length,EncodingName=enc.WebName}; bool md=System.IO.Path.GetExtension(path).Equals(".md",StringComparison.OrdinalIgnoreCase)||System.IO.Path.GetExtension(path).Equals(".markdown",StringComparison.OrdinalIgnoreCase); bool code=false;
   using(var r=new StringReader(body)) {string line; while((line=r.ReadLine())!=null){
    if(md && (line.TrimStart().StartsWith("```")||line.TrimStart().StartsWith("~~~"))){code=!code;continue;}
    if(String.IsNullOrWhiteSpace(line)){continue;}
    int kind=0; string s=line.Trim();
    if(code) {kind=4;s=line;}
    else if(md && Regex.IsMatch(s,@"^#{1,6}\s")){int n=s.TakeWhile(c=>c=='#').Count(); kind=n<=2?1:2; s=s.Substring(n).Trim().TrimEnd('#').Trim();}
    else if(Regex.IsMatch(s,@"^第[零〇一二三四五六七八九十百千万两0-9]+[章节卷部篇回].{0,70}$")){kind=1;}
    else if(md && s.StartsWith(">")){kind=3;s=s.TrimStart('>',' ');}
    else if(md && Regex.IsMatch(s,@"^[-*+]\s")){s="•  "+s.Substring(2);kind=5;}
    else if(md && Regex.IsMatch(s,@"^([-*_])\1{2,}$")){s="────────────────";kind=3;}
    // Bound individual visual elements, even for files with no line breaks.
    for(int i=0;i<s.Length;i+=1200) {int len=Math.Min(1200,s.Length-i); if(i+len<s.Length && Char.IsHighSurrogate(s[i+len-1]))len--; var p=new Paragraph{Text=s.Substring(i,len),Kind=kind,Index=doc.Blocks.Count,Markdown=md};doc.Blocks.Add(p);if((kind==1||kind==2)&&i==0)doc.Chapters.Add(p);if(len<1200 && i+len<s.Length)i--;}
   }}
   if(doc.Blocks.Count==0)doc.Blocks.Add(new Paragraph{Text="这份文件暂时没有文字。",Index=0});return doc;
  }
 }
 public class ReaderText:TextBlock {
  public static string Query="";
  public ReaderText(){TextWrapping=TextWrapping.Wrap; DataContextChanged+=(s,e)=>Render();}
  void Render(){var p=DataContext as Paragraph;if(p==null)return;Inlines.Clear();SetBinding(FontSizeProperty,new System.Windows.Data.Binding("FontSize"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.FindAncestor,typeof(ListBox),1),Converter=new HeadingSize(),ConverterParameter=p.Kind}); Margin=new Thickness(8,p.Kind==1?30:8,8,p.Kind==1?18:10); FontWeight=p.Kind==1||p.Kind==2?FontWeights.SemiBold:FontWeights.Normal; FontStyle=p.Kind==3?FontStyles.Italic:FontStyles.Normal;
   if(p.Kind==4){FontFamily=new FontFamily("Consolas");SetResourceReference(BackgroundProperty,"Code");Padding=new Thickness(16,8,16,8);} else {ClearValue(FontFamilyProperty);ClearValue(BackgroundProperty);Padding=new Thickness(0);}
   string t=p.Text;
   if(Query.Length>0){int start=0,pos;while((pos=t.IndexOf(Query,start,StringComparison.OrdinalIgnoreCase))>=0){Inlines.Add(new Run(t.Substring(start,pos-start)));Inlines.Add(new Run(t.Substring(pos,Query.Length)){Background=new SolidColorBrush(Color.FromRgb(241,200,105)),Foreground=Brushes.Black});start=pos+Query.Length;}Inlines.Add(new Run(t.Substring(start)));}
   else if(p.Kind!=4&&p.Markdown){foreach(var part in Regex.Split(t,@"(\*\*[^*]+\*\*|`[^`]+`|\[[^\]]+\]\([^)]*\))")){if(part.StartsWith("**")&&part.EndsWith("**")&&part.Length>4)Inlines.Add(new Bold(new Run(part.Substring(2,part.Length-4))));else if(part.StartsWith("`")&&part.EndsWith("`")&&part.Length>2)Inlines.Add(new Run(part.Substring(1,part.Length-2)){FontFamily=new FontFamily("Consolas")});else if(part.StartsWith("[")&&part.Contains("]("))Inlines.Add(new Run(part.Substring(1,part.IndexOf("](")-1)));else Inlines.Add(new Run(part));}}
   else Inlines.Add(new Run(t));
  }
 }
