  void ImportFolder(){if(loading)return;using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="选择小说文件夹，导入其中支持的书籍（含子文件夹）",ShowNewFolderButton=false}){if(d.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;try{var paths=Directory.EnumerateFiles(d.SelectedPath,"*",SearchOption.AllDirectories).Where(f=>Formats.Extensions.Contains(System.IO.Path.GetExtension(f).ToLowerInvariant())).ToArray();if(paths.Length==0){status.Text="这个文件夹里没有支持的书籍。";return;}ImportFiles(paths,false,"自动");}catch(Exception ex){MessageBox.Show(this,ex.Message,"无法读取文件夹");}}}
  void DeleteBookClick(object sender,RoutedEventArgs e){e.Handled=true;if(loading)return;var book=((FrameworkElement)sender).DataContext as Book;if(book==null)return;var answer=MessageBox.Show(this,"删除《"+book.Name+"》？\n\n将移除书库记录、阅读进度、书签和书库内的副本。\n你原本导入的来源文件会保留。","删除书籍",MessageBoxButton.YesNo,MessageBoxImage.Question,MessageBoxResult.No);if(answer!=MessageBoxResult.Yes)return;try{saveTimer.Stop();string warning=store.Remove(settings,book);if(Object.ReferenceEquals(current,book)){current=null;document=null;units.Clear();page=null;pageHistory.Clear();reader.ItemsSource=null;matches.Clear();ReaderText.Query="";}RefreshLibrary();RefreshNav();status.Text=warning??"已删除《"+book.Name+"》，来源文件已保留。";}catch(Exception ex){MessageBox.Show(this,"未能删除，书库记录已保留。\n"+ex.Message,"删除失败",MessageBoxButton.OK,MessageBoxImage.Warning);}}
  void RefreshLibrary(){if(bookshelf==null)return;string query=librarySearch.Text.Trim();bookshelf.ItemsSource=settings.Books.Where(b=>query.Length==0||b.Name.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||(b.Author??"").IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).OrderByDescending(b=>b.LastReadUtc??"").ToList();libraryCount.Text=settings.Books.Count==0?"拖入书籍，开始收藏你的阅读时光。支持 TXT · MD · EPUB · DOCX · HTML · FB2":String.Format("共 {0} 本书 · 点击继续上次阅读 · 本地副本长期保存",settings.Books.Count);}
  void ShowLibrary(){if(libraryView==null)return;CapturePosition();Save();saveTimer.Stop();layout.Visibility=Visibility.Collapsed;libraryView.Visibility=Visibility.Visible;top.Visibility=Visibility.Visible;title.Text="我的书库";meta.Text="离线收藏 / 阅读位置自动保存";status.Text="书库已保存 · 顶部「我的书签」可查看全部收藏位置";progress.Text="TXT · MD · EPUB · DOCX · HTML · FB2";RefreshLibrary();}
  void ApplyTheme(string name){settings.Theme=name;bool dark=name=="night",warm=name=="warm";string[] colors=dark?new[]{"#171D24","#202832","#DFE6EC","#93A4B4","#34404D","#8DC8B4","#283440"}:warm?new[]{"#F4EBD8","#EDE2CC","#413C30","#8B806B","#DDCFB4","#477060","#E8DDC7"}:new[]{"#FAFAF7","#F0F2EE","#293831","#7C8B82","#DFE5DE","#376C55","#EAF0E8"};string[] keys={"Bg","Panel","Ink","Muted","Line","Accent","Code"};for(int i=0;i<keys.Length;i++)Resources[keys[i]]=new SolidColorBrush((Color)ColorConverter.ConvertFromString(colors[i]));Resources["ButtonLine"]=new SolidColorBrush((Color)ColorConverter.ConvertFromString(dark?"#8196AA":warm?"#8A744D":"#73887A"));Resources["SearchFill"]=new SolidColorBrush((Color)ColorConverter.ConvertFromString(dark?"#2B3F43":warm?"#E2ECE6":"#E7EFEA"));Resources["ScrollThumb"]=new SolidColorBrush((Color)ColorConverter.ConvertFromString(dark?"#8DB6AC":warm?"#8A7854":"#6D8D7B"));}
  void Save(){try{store.Save(settings);}catch(Exception ex){status.Text="书库未能保存："+ex.Message;}}
  void OpenDialog(){if(loading)return;var d=new OpenFileDialog{Filter=Formats.Filter,Multiselect=true,Title="导入书籍，可同时选择多本"};if(d.ShowDialog(this)==true)ImportFiles(d.FileNames,d.FileNames.Length==1,"自动");}
  public void Open(string path,string forced){var book=settings.Books.FirstOrDefault(b=>String.Equals(b.Path,path,StringComparison.OrdinalIgnoreCase)||String.Equals(b.SourcePath,path,StringComparison.OrdinalIgnoreCase));if(book!=null&&!String.IsNullOrEmpty(book.Id)&&File.Exists(book.Path))OpenBook(book,forced);else ImportFiles(new[]{path},true,forced);}
  async void ImportFiles(string[] paths,bool openSingle,string forced){if(loading)return;CapturePosition();Save();saveTimer.Stop();loading=true;var errors=new List<string>();Book last=null;Document lastDoc=null;int successes=0;watch.Restart();foreach(string path in paths){status.Text=String.Format("正在导入 {0}/{1} · {2}",successes+errors.Count+1,paths.Length,System.IO.Path.GetFileName(path));try{var prepared=await Task.Run(()=>store.Prepare(path,forced));last=store.Register(settings,prepared);lastDoc=prepared.Document;successes++;Save();}catch(Exception ex){errors.Add(System.IO.Path.GetFileName(path)+"："+ex.Message);}}loading=false;RefreshLibrary();RefreshNav();if(openSingle&&last!=null){loading=true;await DisplayBook(last,lastDoc);loading=false;}else ShowLibrary();status.Text=String.Format("导入完成 · {0} 本成功 · {1} 本失败 · 本地书库已保存",successes,errors.Count);if(errors.Count>0)MessageBox.Show(this,String.Join("\n",errors.Take(12)),"部分书籍未能导入",MessageBoxButton.OK,MessageBoxImage.Information);}
  async void OpenBook(Book book,string forced,int? bookmark=null){if(loading)return;if(String.IsNullOrEmpty(book.Id)){ImportFiles(new[]{book.Path},true,forced);return;}CapturePosition();Save();saveTimer.Stop();loading=true;status.Text="正在打开书籍…";watch.Restart();try{string useEncoding=forced=="自动"?book.Encoding:forced;var doc=await Task.Run(()=>Document.Read(book.Path,useEncoding));book.Encoding=useEncoding;if(bookmark.HasValue){book.Position=bookmark.Value;book.VisualPart=0;book.PageCharacter=0;book.ParagraphOffset=0;}await DisplayBook(book,doc);status.Text=String.Format("打开 {0:N0} ms · 已恢复上次位置 · {1:N0} 段",watch.ElapsedMilliseconds,doc.Blocks.Count);}catch(Exception ex){status.Text="未能打开书籍";MessageBox.Show(this,ex.Message+"\n\n如书库文件被移除，请从原始文件重新导入。","无法读取",MessageBoxButton.OK,MessageBoxImage.Warning);}finally{loading=false;}}
  async Task DisplayBook(Book book,Document doc){int logical=Math.Max(0,Math.Min(book.Position,doc.Blocks.Count-1));int part=book.VisualPart;int character=book.PageCharacter;double fraction=book.ParagraphOffset;restoringPosition=true;document=doc;current=book;units=ReadingUnit.Build(doc);page=null;pageHistory.Clear();book.TotalBlocks=doc.Blocks.Count;book.LastReadUtc=DateTime.UtcNow.ToString("o");title.Text=book.Name;meta.Text=String.Format("{0:N0} 字符 / {1}",doc.Characters,doc.EncodingName);search.Text="";ReaderText.Query="";matches.Clear();reader.ItemsSource=units;welcome.Visibility=Visibility.Collapsed;libraryView.Visibility=Visibility.Collapsed;layout.Visibility=Visibility.Visible;side.Visibility=Visibility.Visible;top.Visibility=Visibility.Visible;layout.ColumnDefinitions[0].Width=new GridLength(245);navMode.SelectedIndex=0;RefreshNav();ApplyModeVisuals();UpdateTypography();int target=ReadingUnit.Find(units,logical,part);await Dispatcher.InvokeAsync(()=>{if(Pages)ShowPage(new ReadingCursor(target,character),0);else ScrollToUnit(target,fraction);},DispatcherPriority.Loaded);await Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ContextIdle);restoringPosition=false;StoreCursor(new ReadingCursor(target,character),fraction);UpdateReadingProgress();Save();}
  void UpdateTypography(){if(reader==null)return;reader.FontSize=settings.FontSize;reader.FontFamily=new FontFamily(settings.Font);TextBlock.SetLineHeight(reader,settings.FontSize*settings.Line);reader.Tag=Math.Max(260,Math.Min(settings.Width,ActualWidth-(side!=null&&side.Visibility==Visibility.Visible?245:0)-100));RefreshPageLayout();}
  void RefreshNav(){if(nav==null)return;if(bookmarkTab!=null){bookmarkTab.Content="书签";bookmarkTab.ToolTip=current==null?"本书书签":"本书有 "+current.Marks.Count+" 处书签";var buttons=new[]{chapterTab,bookmarkTab,recentTab};for(int n=0;n<buttons.Length;n++)if(buttons[n]!=null){buttons[n].SetResourceReference(Control.BackgroundProperty,navMode.SelectedIndex==n?"SearchFill":"Panel");buttons[n].SetResourceReference(Control.BorderBrushProperty,navMode.SelectedIndex==n?"Accent":"ButtonLine");}}restoring=true;nav.ItemsSource=null;nav.DisplayMemberPath="Display";if(navMode.SelectedIndex==2){nav.DisplayMemberPath="";nav.ItemsSource=settings.Books.ToList();}else if(document!=null){nav.ItemsSource=navMode.SelectedIndex==0?document.Chapters:current.Marks.Where(i=>i>=0&&i<document.Blocks.Count).OrderBy(i=>i).Select(i=>document.Blocks[i]).ToList();}restoring=false;}
  double ViewTop(){var viewport=FindVisual<ScrollContentPresenter>(reader);return viewport==null?0:viewport.TransformToAncestor(reader).Transform(new Point()).Y;}
  int VisibleIndex(){return units.Count==0?0:units[Pages&&page!=null?page.Start.Unit:TopUnit()].LogicalIndex;}
  static T FindVisual<T>(DependencyObject obj) where T:DependencyObject {for(int i=0;i<VisualTreeHelper.GetChildrenCount(obj);i++){var c=VisualTreeHelper.GetChild(obj,i);if(c is T)return (T)c;var r=FindVisual<T>(c);if(r!=null)return r;}return null;}
  void CapturePosition(){CaptureReadingPosition();}
  void UpdateProgress(int unused){UpdateReadingProgress();}
  void OnScroll(object sender,ScrollChangedEventArgs e){ReadingScrolled();}
  void Jump(int index){JumpLogical(index);}
  void FindNext(){if(document==null)return;string q=search.Text.Trim();if(q.Length==0){ReaderText.Query="";reader.Items.Refresh();matches.Clear();return;}if(q!=ReaderText.Query){ReaderText.Query=q;matches=document.Blocks.Where(p=>p.Text.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0).Select(p=>p.Index).ToList();matchIndex=-1;reader.Items.Refresh();}if(matches.Count==0){status.Text="没有找到「"+q+"」";return;}matchIndex=(matchIndex+1)%matches.Count;Jump(matches[matchIndex]);status.Text=String.Format("搜索：{0} / {1} 个匹配段落（Enter 下一处）",matchIndex+1,matches.Count);}
  void ToggleMark(){if(current==null||layout.Visibility!=Visibility.Visible)return;int i=VisibleIndex();if(current.Marks.Contains(i)){current.Marks.Remove(i);status.Text="已移除当前位置的书签";}else{current.Marks.Add(i);status.Text="已添加书签 · 点击左侧「书签」或顶部「我的书签」查看";}RefreshNav();Save();}
  void FocusMode(){if(layout.Visibility!=Visibility.Visible)return;bool show=side.Visibility!=Visibility.Visible;side.Visibility=show?Visibility.Visible:Visibility.Collapsed;layout.ColumnDefinitions[0].Width=new GridLength(show?245:0);top.Visibility=show?Visibility.Visible:Visibility.Collapsed;UpdateTypography();}
  void OnKey(object s,KeyEventArgs e){if(PagingKey(e))return;if(e.Key==Key.F11){FocusMode();e.Handled=true;}if(Keyboard.Modifiers==ModifierKeys.Control){if(e.Key==Key.O){OpenDialog();e.Handled=true;}if(e.Key==Key.F){if(libraryView.Visibility==Visibility.Visible){librarySearch.Focus();librarySearch.SelectAll();}else{if(side.Visibility!=Visibility.Visible)FocusMode();search.Focus();search.SelectAll();}e.Handled=true;}if(e.Key==Key.D){ToggleMark();e.Handled=true;}if(e.Key==Key.H){ShowLibrary();e.Handled=true;}}if(e.Key==Key.Escape&&side.Visibility!=Visibility.Visible)FocusMode();}
  void ShowSettings(){var w=new Window{Title="阅读设置",Owner=this,Width=420,Height=670,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=B("Panel"),Foreground=B("Ink"),FontFamily=FontFamily,Resources=Resources};var p=new StackPanel{Margin=new Thickness(26)};w.Content=new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};p.Children.Add(new TextBlock{Text="把阅读调成你喜欢的样子",FontSize=20,Margin=new Thickness(0,0,0,20)});var themes=new StackPanel{Orientation=Orientation.Horizontal};p.Children.Add(themes);themes.Children.Add(Btn("纸白",()=>{ApplyTheme("paper");w.Background=B("Panel");w.Foreground=B("Ink");}));themes.Children.Add(Btn("暖砂",()=>{ApplyTheme("warm");w.Background=B("Panel");w.Foreground=B("Ink");}));themes.Children.Add(Btn("深夜",()=>{ApplyTheme("night");w.Background=B("Panel");w.Foreground=B("Ink");}));
   AddLabel(p,"字体");font=new ComboBox{ItemsSource=new[]{"Microsoft YaHei UI","SimSun","KaiTi","Segoe UI"},SelectedItem=settings.Font,Padding=new Thickness(8)};font.SelectionChanged+=(s,e)=>{settings.Font=(string)font.SelectedItem;UpdateTypography();};p.Children.Add(font);
   AddLabel(p,"字号");size=MakeSlider(p,14,34,settings.FontSize,v=>settings.FontSize=v);AddLabel(p,"行距");line=MakeSlider(p,1.3,2.4,settings.Line,v=>settings.Line=v);AddLabel(p,"正文宽度");width=MakeSlider(p,480,1100,settings.Width,v=>settings.Width=v);
   AddLabel(p,"文字乱码时，切换编码重新打开");encoding=new ComboBox{ItemsSource=new[]{"自动","UTF-8","GB18030"},SelectedIndex=0,Padding=new Thickness(7)};encoding.Margin=new Thickness(3,0,3,14);p.Children.Add(encoding);var applyEncoding=Btn("应用编码",()=>{if(current!=null)Open(current.Path,(string)encoding.SelectedItem);});applyEncoding.Margin=new Thickness(3,0,3,14);p.Children.Add(applyEncoding);var done=Btn("完成",()=>w.Close());done.Margin=new Thickness(3,0,3,0);p.Children.Add(done);w.Closed+=(s,e)=>Save();w.ShowDialog();}
  void AddLabel(StackPanel p,string t){p.Children.Add(new TextBlock{Text=t,Margin=new Thickness(0,15,0,8),FontSize=12});}
  Slider MakeSlider(StackPanel p,double min,double max,double value,Action<double> set){var s=new Slider{Minimum=min,Maximum=max,Value=value,TickFrequency=max>10?1:.05,IsSnapToTickEnabled=true};s.ValueChanged+=(a,e)=>{set(s.Value);UpdateTypography();};p.Children.Add(s);return s;}
 }
 public class Program {
  [STAThread] public static void Main(string[] args){if(args.Length>0&&args[0]=="--self-test"){Tests.Run(args.Length>1?args[1]:null);return;}if(args.Length>1&&args[0]=="--make-fixture"){Directory.CreateDirectory(args[1]);IntegrationTests.CreateEpub(args[1]);return;}if(args.Length>2&&args[0]=="--prepare-preview"){IntegrationTests.PreparePreview(args[1],args[2]);return;}var app=new Application();app.DispatcherUnhandledException+=(s,e)=>{MessageBox.Show(e.Exception.Message,"静阅");e.Handled=true;};bool isolated=args.Length>1&&args[0]=="--data-root";string dataRoot=isolated?args[1]:null;
#if PREVIEW
   dataRoot=System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"preview-data");
#endif
   bool first;using(var instance=new System.Threading.Mutex(true,@"Local\JingYue-"+(dataRoot??"default").GetHashCode(),out first)){if(!first){MessageBox.Show("静阅已在运行，请使用已打开的窗口。","静阅");return;}var w=new MainWindow(dataRoot);if(args.Length>0&&!isolated)w.Loaded+=(s,e)=>w.Open(args[0],"自动");app.Run(w);}}
 }
 public static class Tests {
  public static void Run(string samples){string dir=System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"JingYueTest-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var report=new StringBuilder();try{
   string md=System.IO.Path.Combine(dir,"test.md");File.WriteAllText(md,"# 标题\n正文 **加粗**\n> 引用\n- 列表\n```c\nvar a=1;\n```",new UTF8Encoding(true));var d=Document.Read(md,"自动");Check(d.Blocks.Count==5&&d.Chapters.Count==1&&d.Blocks[4].Kind==4,"Markdown blocks",report);
   string txt=System.IO.Path.Combine(dir,"test.txt");File.WriteAllText(txt,"第一章 开始\n中文简体繁體測試",Encoding.GetEncoding("GB18030"));d=Document.Read(txt,"自动");Check(d.Chapters.Count==1&&d.Blocks[1].Text=="中文简体繁體測試","GB18030 auto detection",report);
   File.WriteAllText(txt,"Unicode 测试",Encoding.Unicode);d=Document.Read(txt,"自动");Check(d.Blocks[0].Text=="Unicode 测试","UTF16 BOM",report);
   string huge=new string('阅',1199)+"😀"+new string('读',18000);File.WriteAllText(txt,huge);d=Document.Read(txt,"自动");Check(String.Concat(d.Blocks.Select(b=>b.Text))==huge&&d.Blocks.All(b=>b.Text.Length<=1200),"Long lines / surrogate preservation",report);
   var big=new StringBuilder();for(int i=0;i<180000;i++)big.AppendLine("长文性能测试：这是一段本地阅读内容，检查目录解析和分段加载。第 "+i+" 段。");File.WriteAllText(txt,big.ToString());var sw=Stopwatch.StartNew();d=Document.Read(txt,"自动");Check(d.Blocks.Count==180000,"180000 paragraph import",report);report.AppendLine("Large file: "+new FileInfo(txt).Length+" bytes, "+sw.ElapsedMilliseconds+" ms");
   File.WriteAllText(txt,"");Check(Document.Read(txt,"自动").Blocks.Count==1,"Empty document",report);
   var xml=new XmlSerializer(typeof(Settings));var cfg=new Settings();cfg.Books.Add(new Book{Path=md,Position=3,Marks=new List<int>{1,3}});using(var ms=new MemoryStream()){xml.Serialize(ms,cfg);ms.Position=0;var copy=(Settings)xml.Deserialize(ms);Check(copy.Books[0].Marks.SequenceEqual(new[]{1,3}),"Reading state persistence",report);}
   IntegrationTests.Run(report);if(samples!=null)IntegrationTests.Samples(samples,report);File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),report.ToString());Console.WriteLine(report.ToString());
  }finally{Directory.Delete(dir,true);}}
  static void Check(bool ok,string name,StringBuilder report){if(!ok)throw new Exception("FAIL: "+name);report.AppendLine("PASS: "+name);}
 }
}